{
  "name": "@razroo/opencode-model-fallback",
  "version": "0.3.2",
  "description": "Automatic model fallback plugin for OpenCode. Switches to backup models when API errors occur.",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist/"
  ],
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/razroo/opencode-model-fallback.git"
  },
  "scripts": {
    "build": "bun run build.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "keywords": [
    "opencode",
    "plugin",
    "fallback",
    "model",
    "ai"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.1.19",
    "@opencode-ai/sdk": ">=1.1.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/sdk": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.19",
    "bun-types": "1.3.6",
    "typescript": "^5.7.3"
  },
  "dependencies": {
    "jsonc-parser": "^3.3.1"
  }
}
